in_so_eta = all(preserves_bilinear_form(v, eta) for v in basis_g)
print(f"Step 8b: g ⊂ so(b_Ω): {in_so_eta} {'(so(3,4)-COMPATIBLE)' if in_so_eta else ''}")
require(in_so_eta, "g is not contained in so(b_Ω)")

